import os, re, csv, json, numpy as np

N = 26
OUT_DIR = 'storage/noesis/nmap/inquire_exports_v1'
TOL_TAG = 'tol1e8'

# Canonicalization for boundary labels and filename variants
CANON = {
  'xl':'xL','x_l':'xL','xleft':'xL','left':'xL','xmin':'xL','x_min':'xL',
  'xr':'xR','x_r':'xR','xright':'xR','right':'xR','xmax':'xR','x_max':'xR',
  'yb':'yB','y_b':'yB','ybottom':'yB','bottom':'yB','ymin':'yB','y_min':'yB',
  'yt':'yT','y_t':'yT','ytop':'yT','top':'yT','ymax':'yT','y_max':'yT',
  'xL':'xL','xR':'xR','yB':'yB','yT':'yT'
}
INT_RE = re.compile(r'[-+]?\d+')
NUM_RE = re.compile(r'[-+]?\d+(?:\.\d+)?', re.I)
SIDE_RE = re.compile(r'(xL|xR|yB|yT|xl|xr|yb|yt|left|right|top|bottom|xmin|xmax|ymin|ymax|x_min|x_max|y_min|y_max)', re.I)

def first_existing(paths):
    for p in paths:
        if p and os.path.exists(p):
            return p
    return None

def read_lines(path):
    with open(path, 'r', encoding='utf-8', errors='ignore') as f:
        return f.read().strip().splitlines()

def parse_pairs_raw(path):
    rows=[]
    if not path or not os.path.exists(path): return rows
    for ln in read_lines(path):
        toks = NUM_RE.findall(ln)
        if len(toks) >= 2:
            try:
                i = int(float(toks[0])); j = int(float(toks[1]))
                rows.append((i, j))
            except Exception:
                continue
    return rows

def parse_boundary_raw(path):
    rows=[]
    if not path or not os.path.exists(path): return rows
    for ln in read_lines(path):
        itoks = INT_RE.findall(ln)
        if not itoks: 
            continue
        try:
            i = int(itoks[0])
        except Exception:
            continue
        m = SIDE_RE.search(ln)
        if not m: 
            continue
        s_raw = m.group(1)
        k = s_raw.replace(' ', '').replace(':','').replace(',','').replace('.','').lower()
        s = CANON.get(k, CANON.get(k.lower(), k))
        if s in ('xL','xR','yB','yT'):
            rows.append((i, s))
    return rows

def normalize_indices(rows, kind):
    # Normalize to 0-based indices, deduplicate pairs with ordering (i<j)
    if kind == 'pairs':
        idxs = [i for (i, _) in rows] + [j for (_, j) in rows]
    else:
        idxs = [i for (i, _) in rows]
    if not idxs:
        return set(), {'applied': False, 'mode': 'empty'}
    c0 = sum(0 <= v <= N-1 for v in idxs)
    c1 = sum(1 <= v <= N for v in idxs)
    meta = {'applied': False, 'mode': 'as-is'}
    out = set()
    if c1 > c0 and all(1 <= v <= N for v in idxs):
        meta = {'applied': True, 'mode': 'minus_one'}
        if kind == 'pairs':
            for (i, j) in rows:
                a, b = i-1, j-1
                if 0 <= a < N and 0 <= b < N and a != b:
                    u, v = (a, b) if a < b else (b, a)
                    out.add((u, v))
        else:
            for (i, s) in rows:
                a = i-1
                if 0 <= a < N:
                    out.add((a, s))
    else:
        if kind == 'pairs':
            for (i, j) in rows:
                if 0 <= i < N and 0 <= j < N and i != j:
                    u, v = (i, j) if i < j else (j, i)
                    out.add((u, v))
        else:
            for (i, s) in rows:
                if 0 <= i < N:
                    out.add((i, s))
    return out, meta

def load_pack_from_dir(dir_root):
    # Accept standard names; if missing, try any CSV with 'active'+'boundary' or 'active'+'pairs'
    b_path = first_existing([
        os.path.join(dir_root, f'active_boundary_{TOL_TAG}.csv'),
        os.path.join(dir_root, 'active_boundary_tol1e-8.csv'),
        os.path.join(dir_root, 'active_boundary_tol1e-08.csv'),
        os.path.join(dir_root, 'active_boundary.csv'),
    ])
    p_path = first_existing([
        os.path.join(dir_root, f'active_pairs_{TOL_TAG}.csv'),
        os.path.join(dir_root, 'active_pairs_tol1e-8.csv'),
        os.path.join(dir_root, 'active_pairs_tol1e-08.csv'),
        os.path.join(dir_root, 'active_pairs.csv'),
    ])
    # Fallback: scan directory for any matching files
    if not b_path or not p_path:
        if os.path.exists(dir_root):
            for fn in os.listdir(dir_root):
                fl = fn.lower()
                full = os.path.join(dir_root, fn)
                if (not b_path) and ('active' in fl and 'boundary' in fl and fl.endswith('.csv')):
                    b_path = full
                if (not p_path) and ('active' in fl and 'pairs' in fl and fl.endswith('.csv')):
                    p_path = full
    pairs_raw = parse_pairs_raw(p_path)
    bound_raw = parse_boundary_raw(b_path)
    pairs, _ = normalize_indices(pairs_raw, 'pairs')
    bound, _ = normalize_indices(bound_raw, 'bound')
    return {'pairs': pairs, 'bound': bound}

def jaccard(A, B):
    I = A & B; U = A | B
    return {'j': (float(len(I))/float(len(U)) if len(U) > 0 else 1.0), 'I': len(I), 'U': len(U)}

def write_json_csv(base, tag, res):
    os.makedirs(base, exist_ok=True)
    with open(os.path.join(base, f'{tag}.json'), 'w') as f:
        json.dump(res, f, indent=2, sort_keys=True)
    with open(os.path.join(base, f'{tag}.csv'), 'w', newline='') as f:
        w = csv.writer(f); w.writerow(['n','boundary_j','I_b','U_b','pairs_j','I_p','U_p'])
        w.writerow([N, res['boundary']['j'], res['boundary']['I'], res['boundary']['U'],
                       res['pairs']['j'],    res['pairs']['I'],    res['pairs']['U']])

def consensus_sets(packs):
    # packs: dict name-> {'bound','pairs'}
    Bs = [packs[k]['bound'] for k in packs]
    Ps = [packs[k]['pairs'] for k in packs]
    inter_b = set.intersection(*Bs) if all(isinstance(s,set) for s in Bs) else set()
    union_b = set.union(*Bs) if all(isinstance(s,set) for s in Bs) else set()
    inter_p = set.intersection(*Ps) if all(isinstance(s,set) for s in Ps) else set()
    union_p = set.union(*Ps) if all(isinstance(s,set) for s in Ps) else set()
    sizes_b = {k: len(packs[k]['bound']) for k in packs}
    sizes_p = {k: len(packs[k]['pairs']) for k in packs}
    return {'boundary': {'intersection': len(inter_b), 'union': len(union_b), 'sizes': sizes_b},
            'pairs':    {'intersection': len(inter_p), 'union': len(union_p), 'sizes': sizes_p}}

def construct_packing():
    os.makedirs(OUT_DIR, exist_ok=True)

    # SOTA packs (sets only)
    noe = load_pack_from_dir('storage/noesis/exports/sota_243')
    sci = load_pack_from_dir('storage/Scientia/nmap/n26')
    pro = load_pack_from_dir('storage/Prometheus/nmap/n26')

    inq_dir = first_existing(['storage/Inquire/exports', 'storage/inquire/exports'])
    inq = load_pack_from_dir(inq_dir) if inq_dir else {'pairs': set(), 'bound': set()}

    # Pairwise Jaccards (unaligned, sets-only)
    comps = {
      'inquire207_vs_noesis243': {'A': inq, 'B': noe},
      'inquire207_vs_scientia259': {'A': inq, 'B': sci},
      'inquire207_vs_prometheus298': {'A': inq, 'B': pro},
    }
    for tag, d in comps.items():
        res = {
          'n': N,
          'boundary': jaccard(d['A']['bound'], d['B']['bound']),
          'pairs':    jaccard(d['A']['pairs'], d['B']['pairs']),
          'note': 'sets-only'
        }
        write_json_csv(OUT_DIR, f'{tag}_{TOL_TAG}', res)

    # 4-lineage consensus (sets-only)
    packs = {'Noesis_243': noe, 'Scientia_259': sci, 'Prometheus_298': pro, 'Inquire_207': inq}
    cons4 = consensus_sets(packs)
    with open(os.path.join(OUT_DIR, f'consensus_4lineage_sets_{TOL_TAG}.json'), 'w') as f:
        json.dump({'n': N, 'ids': list(packs.keys()), **cons4}, f, indent=2, sort_keys=True)

    # Return current Noesis packing unchanged
    c = np.loadtxt('storage/noesis/latest_centers.txt'); r = np.loadtxt('storage/noesis/latest_radii.txt')
    return np.array(c, float).reshape(N, 2), np.array(r, float).reshape(N,)
